(7538586, 1206010, 67723, '<td valign="top">Favorite! Love this photo, such beautiful colors.</td>', 'Favorite! Love this photo, such beautiful colors.', '2017-10-09 01:21:20.000000', NULL, 1),
(7538587, 1206548, 67723, '<td valign="top">Second favorite! Hope this does well. Good strong composition.</td>', 'Second favorite! Hope this does well. Good strong composition.', '2017-10-09 01:21:42.000000', NULL, 1),
(7538605, 1206170, 6519, '<td valign="top">It is a lovely scene and I''m trying so hard to ignore all those spots, but it is quite impossible. I do hope that was merely fine water spray on the glass, rather than millions of dust bunnies on your sensor!!!</td>', 'It is a lovely scene and I''m trying so hard to ignore all those spots, but it is quite impossible. I do hope that was merely fine water spray on the glass, rather than millions of dust bunnies on your sensor!!!', '2017-10-09 03:43:06.000000', NULL, 1),
(7538606, 1206467, 6519, '<td valign="top">Seeing how the topic is about water, I would have preferred a slightly different angle to show more reflection, less "original". But it is a lovely scene, nevertheless.</td>', 'Seeing how the topic is about water, I would have preferred a slightly different angle to show more reflection, less "original". But it is a lovely scene, nevertheless.', '2017-10-09 03:47:35.000000', NULL, 1),
(7538607, 1205925, 6519, '<td valign="top">Aaaawwww, this is so lovely! And only about 120km away from my former home, Landshut. Looks rather similar, too :-)</td>', 'Aaaawwww, this is so lovely! And only about 120km away from my former home, Landshut. Looks rather similar, too :-)', '2017-10-09 04:04:43.000000', NULL, 1),
